static const char src_zfast_crt[] =
    "/*\n"
    "    zfast_crt_standard - A simple, fast CRT shader.\n"
    "\n"
    "    Copyright (C) 2017 Greg Hogan (SoltanGris42)\n"
    "\n"
    "    This program is free software; you can redistribute it and/or modify it\n"
    "    under the terms of the GNU General Public License as published by the Free\n"
    "    Software Foundation; either version 2 of the License, or (at your option)\n"
    "    any later version.\n"
    "\n"
    "\n"
    "Notes:  This shader does scaling with a weighted linear filter for adjustable\n"
    "    sharpness on the x and y axes based on the algorithm by Inigo Quilez here:\n"
    "    http://http://www.iquilezles.org/www/articles/texture/texture.htm\n"
    "    but modified to be somewhat sharper.  Then a scanline effect that varies\n"
    "    based on pixel brighness is applied along with a monochrome aperture mask.\n"
    "    This shader runs at 60fps on the Raspberry Pi 3 hardware at 2mpix/s\n"
    "    resolutions (1920x1080 or 1600x1200).\n"
    "*/\n"
    "\n"
    "//For testing compilation \n"
    "//#define FRAGMENT\n"
    "//#define VERTEX\n"
    "\n"
    "//This can't be an option without slowing the shader down\n"
    "//Comment this out for a coarser 3 pixel mask...which is currently broken\n"
    "//on SNES Classic Edition due to Mali 400 gpu precision\n"
    "#define FINEMASK\n"
    "//Some drivers don't return black with texture coordinates out of bounds\n"
    "//SNES Classic is too slow to black these areas out when using fullscreen\n"
    "//overlays.  But you can uncomment the below to black them out if necessary\n"
    "//#define BLACK_OUT_BORDER\n"
    "\n"
    "// Parameter lines go here:\n"
    "#pragma parameter BLURSCALEX \"Blur Amount X-Axis\" 0.30 0.0 1.0 0.05\n"
    "#pragma parameter LOWLUMSCAN \"Scanline Darkness - Low\" 6.0 0.0 10.0 0.5\n"
    "#pragma parameter HILUMSCAN \"Scanline Darkness - High\" 8.0 0.0 50.0 1.0\n"
    "#pragma parameter BRIGHTBOOST \"Dark Pixel Brightness Boost\" 1.25 0.5 1.5 0.05\n"
    "#pragma parameter MASK_DARK \"Mask Effect Amount\" 0.25 0.0 1.0 0.05\n"
    "#pragma parameter MASK_FADE \"Mask/Scanline Fade\" 0.8 0.0 1.0 0.05\n"
    "\n"
    "#if defined(VERTEX)\n"
    "\n"
    "#if __VERSION__ >= 130\n"
    "#define COMPAT_VARYING out\n"
    "#define COMPAT_ATTRIBUTE in\n"
    "#define COMPAT_TEXTURE texture\n"
    "#else\n"
    "#define COMPAT_VARYING varying \n"
    "#define COMPAT_ATTRIBUTE attribute \n"
    "#define COMPAT_TEXTURE texture2D\n"
    "#endif\n"
    "\n"
    "#ifdef GL_ES\n"
    "#ifdef GL_FRAGMENT_PRECISION_HIGH\n"
    "#define COMPAT_PRECISION highp\n"
    "#else\n"
    "#define COMPAT_PRECISION mediump\n"
    "#endif\n"
    "#else\n"
    "#define COMPAT_PRECISION\n"
    "#endif\n"
    "\n"
    "COMPAT_ATTRIBUTE vec4 VertexCoord;\n"
    "COMPAT_ATTRIBUTE vec4 COLOR;\n"
    "COMPAT_ATTRIBUTE vec4 TexCoord;\n"
    "COMPAT_VARYING vec4 COL0;\n"
    "COMPAT_VARYING vec4 TEX0;\n"
    "COMPAT_VARYING float maskFade;\n"
    "COMPAT_VARYING vec2 invDims;\n"
    "\n"
    "vec4 _oPosition1; \n"
    "uniform mat4 MVPMatrix;\n"
    "uniform COMPAT_PRECISION int FrameDirection;\n"
    "uniform COMPAT_PRECISION int FrameCount;\n"
    "uniform COMPAT_PRECISION vec2 OutputSize;\n"
    "uniform COMPAT_PRECISION vec2 TextureSize;\n"
    "uniform COMPAT_PRECISION vec2 InputSize;\n"
    "\n"
    "// compatibility #defines\n"
    "#define vTexCoord TEX0.xy\n"
    "#define SourceSize vec4(TextureSize, 1.0 / TextureSize) //either TextureSize or InputSize\n"
    "#define OutSize vec4(OutputSize, 1.0 / OutputSize)\n"
    "\n"
    "#ifdef PARAMETER_UNIFORM\n"
    "// All parameter floats need to have COMPAT_PRECISION in front of them\n"
    "uniform COMPAT_PRECISION float BLURSCALEX;\n"
    "//uniform COMPAT_PRECISION float BLURSCALEY;\n"
    "uniform COMPAT_PRECISION float LOWLUMSCAN;\n"
    "uniform COMPAT_PRECISION float HILUMSCAN;\n"
    "uniform COMPAT_PRECISION float BRIGHTBOOST;\n"
    "uniform COMPAT_PRECISION float MASK_DARK;\n"
    "uniform COMPAT_PRECISION float MASK_FADE;\n"
    "#else\n"
    "#define BLURSCALEX 0.45\n"
    "//#define BLURSCALEY 0.20\n"
    "#define LOWLUMSCAN 5.0\n"
    "#define HILUMSCAN 10.0\n"
    "#define BRIGHTBOOST 1.25\n"
    "#define MASK_DARK 0.25\n"
    "#define MASK_FADE 0.8\n"
    "#endif\n"
    "\n"
    "void main()\n"
    "{\n"
    "    gl_Position = MVPMatrix * VertexCoord;\n"
    "    \n"
    "    TEX0.xy = TexCoord.xy*1.0001;\n"
    "    maskFade = 0.3333*MASK_FADE;\n"
    "    invDims = 1.0/TextureSize.xy;\n"
    "}\n"
    "\n"
    "#elif defined(FRAGMENT)\n"
    "\n"
    "#ifdef GL_ES\n"
    "#ifdef GL_FRAGMENT_PRECISION_HIGH\n"
    "precision highp float;\n"
    "#else\n"
    "precision mediump float;\n"
    "#endif\n"
    "#ifdef GL_FRAGMENT_PRECISION_HIGH\n"
    "#define COMPAT_PRECISION highp\n"
    "#else \n"
    "#define COMPAT_PRECISION mediump\n"
    "#endif\n"
    "#else\n"
    "#define COMPAT_PRECISION\n"
    "#endif\n"
    "\n"
    "#if __VERSION__ >= 130\n"
    "#define COMPAT_VARYING in\n"
    "#define COMPAT_TEXTURE texture\n"
    "out COMPAT_PRECISION vec4 FragColor;\n"
    "#else\n"
    "#define COMPAT_VARYING varying\n"
    "#define FragColor gl_FragColor\n"
    "#define COMPAT_TEXTURE texture2D\n"
    "#endif\n"
    "\n"
    "uniform COMPAT_PRECISION int FrameDirection;\n"
    "uniform COMPAT_PRECISION int FrameCount;\n"
    "uniform COMPAT_PRECISION vec2 OutputSize;\n"
    "uniform COMPAT_PRECISION vec2 TextureSize;\n"
    "uniform COMPAT_PRECISION vec2 InputSize;\n"
    "uniform sampler2D Texture;\n"
    "COMPAT_VARYING vec4 TEX0;\n"
    "COMPAT_VARYING float maskFade;\n"
    "COMPAT_VARYING vec2 invDims;\n"
    "\n"
    "// compatibility #defines\n"
    "#define Source Texture\n"
    "#define vTexCoord TEX0.xy\n"
    "#define texture(c, d) COMPAT_TEXTURE(c, d)\n"
    "#define SourceSize vec4(TextureSize, 1.0 / TextureSize) //either TextureSize or InputSize\n"
    "#define OutSize vec4(OutputSize, 1.0 / OutputSize)\n"
    "\n"
    "#ifdef PARAMETER_UNIFORM\n"
    "// All parameter floats need to have COMPAT_PRECISION in front of them\n"
    "uniform COMPAT_PRECISION float BLURSCALEX;\n"
    "//uniform COMPAT_PRECISION float BLURSCALEY;\n"
    "uniform COMPAT_PRECISION float LOWLUMSCAN;\n"
    "uniform COMPAT_PRECISION float HILUMSCAN;\n"
    "uniform COMPAT_PRECISION float BRIGHTBOOST;\n"
    "uniform COMPAT_PRECISION float MASK_DARK;\n"
    "uniform COMPAT_PRECISION float MASK_FADE;\n"
    "#else\n"
    "#define BLURSCALEX 0.45\n"
    "//#define BLURSCALEY 0.20\n"
    "#define LOWLUMSCAN 5.0\n"
    "#define HILUMSCAN 10.0\n"
    "#define BRIGHTBOOST 1.25\n"
    "#define MASK_DARK 0.25\n"
    "#define MASK_FADE 0.8\n"
    "#endif\n"
    "\n"
    "void main()\n"
    "{\n"
    "\n"
    "    //This is just like \"Quilez Scaling\" but sharper\n"
    "    COMPAT_PRECISION vec2 p = vTexCoord * TextureSize;\n"
    "    COMPAT_PRECISION vec2 i = floor(p) + 0.50;\n"
    "    COMPAT_PRECISION vec2 f = p - i;\n"
    "    p = (i + 4.0*f*f*f)*invDims;\n"
    "    p.x = mix( p.x , vTexCoord.x, BLURSCALEX);\n"
    "    COMPAT_PRECISION float Y = f.y*f.y;\n"
    "    COMPAT_PRECISION float YY = Y*Y;\n"
    "#define ratio SourceSize.x/InputSize.x    \n"
    "#if defined(FINEMASK) \n"
    "    COMPAT_PRECISION float whichmask = floor(vTexCoord.x*OutputSize.x*ratio)*-0.5;\n"
    "    COMPAT_PRECISION float mask = 1.0 + float(fract(whichmask) < 0.5) * -MASK_DARK;\n"
    "#else\n"
    "    COMPAT_PRECISION float whichmask = floor(vTexCoord.x*OutputSize.x*ratio)*-0.3333;\n"
    "    COMPAT_PRECISION float mask = 1.0 + float(fract(whichmask) < 0.3333) * -MASK_DARK;\n"
    "#endif\n"
    "    COMPAT_PRECISION vec3 colour = COMPAT_TEXTURE(Source, p).rgb;\n"
    "    \n"
    "    COMPAT_PRECISION float scanLineWeight = (BRIGHTBOOST - LOWLUMSCAN*(Y - 2.05*YY));\n"
    "    COMPAT_PRECISION float scanLineWeightB = 1.0 - HILUMSCAN*(YY-2.8*YY*Y);    \n"
    "    \n"
    "#if defined(BLACK_OUT_BORDER)\n"
    "    colour.rgb*=float(tc.x > 0.0)*float(tc.y > 0.0); //why doesn't the driver do the right thing?\n"
    "#endif\n"
    "\n"
    "    FragColor.rgba = vec4(colour.rgb*mix(scanLineWeight*mask, scanLineWeightB, dot(colour.rgb,vec3(maskFade))),1.0);\n"
    "    \n"
    "} \n"
    "#endif\n"
    "\n";

static const char src_crt_pi[] =
    "/*\n"
    "    crt-pi - A Raspberry Pi friendly CRT shader.\n"
    "\n"
    "    Copyright (C) 2015-2016 davej\n"
    "\n"
    "    This program is free software; you can redistribute it and/or modify it\n"
    "    under the terms of the GNU General Public License as published by the Free\n"
    "    Software Foundation; either version 2 of the License, or (at your option)\n"
    "    any later version.\n"
    "\n"
    "\n"
    "Notes:\n"
    "\n"
    "This shader is designed to work well on Raspberry Pi GPUs (i.e. 1080P @ 60Hz on a game with a 4:3 aspect ratio). It pushes the Pi's GPU hard and enabling some features will slow it down so that it is no longer able to match 1080P @ 60Hz. You will need to overclock your Pi to the fastest setting in raspi-config to get the best results from this shader: 'Pi2' for Pi2 and 'Turbo' for original Pi and Pi Zero. Note: Pi2s are slower at running the shader than other Pis, this seems to be down to Pi2s lower maximum memory speed. Pi2s don't quite manage 1080P @ 60Hz - they drop about 1 in 1000 frames. You probably won't notice this, but if you do, try enabling FAKE_GAMMA.\n"
    "\n"
    "SCANLINES enables scanlines. You'll almost certainly want to use it with MULTISAMPLE to reduce moire effects. SCANLINE_WEIGHT defines how wide scanlines are (it is an inverse value so a higher number = thinner lines). SCANLINE_GAP_BRIGHTNESS defines how dark the gaps between the scan lines are. Darker gaps between scan lines make moire effects more likely.\n"
    "\n"
    "GAMMA enables gamma correction using the values in INPUT_GAMMA and OUTPUT_GAMMA. FAKE_GAMMA causes it to ignore the values in INPUT_GAMMA and OUTPUT_GAMMA and approximate gamma correction in a way which is faster than true gamma whilst still looking better than having none. You must have GAMMA defined to enable FAKE_GAMMA.\n"
    "\n"
    "CURVATURE distorts the screen by CURVATURE_X and CURVATURE_Y. Curvature slows things down a lot.\n"
    "\n"
    "By default the shader uses linear blending horizontally. If you find this too blury, enable SHARPER.\n"
    "\n"
    "BLOOM_FACTOR controls the increase in width for bright scanlines.\n"
    "\n"
    "MASK_TYPE defines what, if any, shadow mask to use. MASK_BRIGHTNESS defines how much the mask type darkens the screen.\n"
    "\n"
    "*/\n"
    "\n"
    "#pragma parameter CURVATURE_X \"Screen curvature - horizontal\" 0.10 0.0 1.0 0.01\n"
    "#pragma parameter CURVATURE_Y \"Screen curvature - vertical\" 0.15 0.0 1.0 0.01\n"
    "#pragma parameter MASK_BRIGHTNESS \"Mask brightness\" 0.70 0.0 1.0 0.01\n"
    "#pragma parameter SCANLINE_WEIGHT \"Scanline weight\" 6.0 0.0 15.0 0.1\n"
    "#pragma parameter SCANLINE_GAP_BRIGHTNESS \"Scanline gap brightness\" 0.12 0.0 1.0 0.01\n"
    "#pragma parameter BLOOM_FACTOR \"Bloom factor\" 1.5 0.0 5.0 0.01\n"
    "#pragma parameter INPUT_GAMMA \"Input gamma\" 2.4 0.0 5.0 0.01\n"
    "#pragma parameter OUTPUT_GAMMA \"Output gamma\" 2.2 0.0 5.0 0.01\n"
    "\n"
    "// Haven't put these as parameters as it would slow the code down.\n"
    "#define SCANLINES\n"
    "#define MULTISAMPLE\n"
    "#define GAMMA\n"
    "//#define FAKE_GAMMA\n"
    "//#define CURVATURE\n"
    "//#define SHARPER\n"
    "// MASK_TYPE: 0 = none, 1 = green/magenta, 2 = trinitron(ish)\n"
    "#define MASK_TYPE 1\n"
    "\n"
    "\n"
    "#ifdef GL_ES\n"
    "#ifdef GL_FRAGMENT_PRECISION_HIGH\n"
    "precision highp float;\n"
    "#else\n"
    "precision mediump float;\n"
    "#endif\n"
    "#ifdef GL_FRAGMENT_PRECISION_HIGH\n"
    "#define COMPAT_PRECISION highp\n"
    "#else \n"
    "#define COMPAT_PRECISION mediump\n"
    "#endif\n"
    "#else\n"
    "#define COMPAT_PRECISION\n"
    "#endif\n"
    "\n"
    "#ifdef PARAMETER_UNIFORM\n"
    "uniform COMPAT_PRECISION float CURVATURE_X;\n"
    "uniform COMPAT_PRECISION float CURVATURE_Y;\n"
    "uniform COMPAT_PRECISION float MASK_BRIGHTNESS;\n"
    "uniform COMPAT_PRECISION float SCANLINE_WEIGHT;\n"
    "uniform COMPAT_PRECISION float SCANLINE_GAP_BRIGHTNESS;\n"
    "uniform COMPAT_PRECISION float BLOOM_FACTOR;\n"
    "uniform COMPAT_PRECISION float INPUT_GAMMA;\n"
    "uniform COMPAT_PRECISION float OUTPUT_GAMMA;\n"
    "#else\n"
    "#define CURVATURE_X 0.10\n"
    "#define CURVATURE_Y 0.25\n"
    "#define MASK_BRIGHTNESS 0.70\n"
    "#define SCANLINE_WEIGHT 6.0\n"
    "#define SCANLINE_GAP_BRIGHTNESS 0.12\n"
    "#define BLOOM_FACTOR 1.5\n"
    "#define INPUT_GAMMA 2.4\n"
    "#define OUTPUT_GAMMA 2.2\n"
    "#endif\n"
    "\n"
    "/* COMPATIBILITY\n"
    "   - GLSL compilers\n"
    "*/\n"
    "\n"
    "uniform vec2 TextureSize;\n"
    "#if defined(CURVATURE)\n"
    "varying vec2 screenScale;\n"
    "#endif\n"
    "varying vec2 TEX0;\n"
    "varying float filterWidth;\n"
    "\n"
    "#if defined(VERTEX)\n"
    "uniform mat4 MVPMatrix;\n"
    "attribute vec4 VertexCoord;\n"
    "attribute vec2 TexCoord;\n"
    "uniform vec2 InputSize;\n"
    "uniform vec2 OutputSize;\n"
    "\n"
    "void main()\n"
    "{\n"
    "#if defined(CURVATURE)\n"
    "    screenScale = TextureSize / InputSize;\n"
    "#endif\n"
    "    filterWidth = (InputSize.y / OutputSize.y) / 3.0;\n"
    "    TEX0 = TexCoord;\n"
    "    gl_Position = MVPMatrix * VertexCoord;\n"
    "}\n"
    "#elif defined(FRAGMENT)\n"
    "\n"
    "uniform sampler2D Texture;\n"
    "\n"
    "#if defined(CURVATURE)\n"
    "vec2 Distort(vec2 coord)\n"
    "{\n"
    "    vec2 CURVATURE_DISTORTION = vec2(CURVATURE_X, CURVATURE_Y);\n"
    "    // Barrel distortion shrinks the display area a bit, this will allow us to counteract that.\n"
    "    vec2 barrelScale = 1.0 - (0.23 * CURVATURE_DISTORTION);\n"
    "    coord *= screenScale;\n"
    "    coord -= vec2(0.5);\n"
    "    float rsq = coord.x * coord.x + coord.y * coord.y;\n"
    "    coord += coord * (CURVATURE_DISTORTION * rsq);\n"
    "    coord *= barrelScale;\n"
    "    if (abs(coord.x) >= 0.5 || abs(coord.y) >= 0.5)\n"
    "        coord = vec2(-1.0);        // If out of bounds, return an invalid value.\n"
    "    else\n"
    "    {\n"
    "        coord += vec2(0.5);\n"
    "        coord /= screenScale;\n"
    "    }\n"
    "\n"
    "    return coord;\n"
    "}\n"
    "#endif\n"
    "\n"
    "float CalcScanLineWeight(float dist)\n"
    "{\n"
    "    return max(1.0-dist*dist*SCANLINE_WEIGHT, SCANLINE_GAP_BRIGHTNESS);\n"
    "}\n"
    "\n"
    "float CalcScanLine(float dy)\n"
    "{\n"
    "    float scanLineWeight = CalcScanLineWeight(dy);\n"
    "#if defined(MULTISAMPLE)\n"
    "    scanLineWeight += CalcScanLineWeight(dy-filterWidth);\n"
    "    scanLineWeight += CalcScanLineWeight(dy+filterWidth);\n"
    "    scanLineWeight *= 0.3333333;\n"
    "#endif\n"
    "    return scanLineWeight;\n"
    "}\n"
    "\n"
    "void main()\n"
    "{\n"
    "#if defined(CURVATURE)\n"
    "    vec2 texcoord = Distort(TEX0);\n"
    "    if (texcoord.x < 0.0)\n"
    "        gl_FragColor = vec4(0.0);\n"
    "    else\n"
    "#else\n"
    "    vec2 texcoord = TEX0;\n"
    "#endif\n"
    "    {\n"
    "        vec2 texcoordInPixels = texcoord * TextureSize;\n"
    "#if defined(SHARPER)\n"
    "        vec2 tempCoord = floor(texcoordInPixels) + 0.5;\n"
    "        vec2 coord = tempCoord / TextureSize;\n"
    "        vec2 deltas = texcoordInPixels - tempCoord;\n"
    "        float scanLineWeight = CalcScanLine(deltas.y);\n"
    "        vec2 signs = sign(deltas);\n"
    "        deltas.x *= 2.0;\n"
    "        deltas = deltas * deltas;\n"
    "        deltas.y = deltas.y * deltas.y;\n"
    "        deltas.x *= 0.5;\n"
    "        deltas.y *= 8.0;\n"
    "        deltas /= TextureSize;\n"
    "        deltas *= signs;\n"
    "        vec2 tc = coord + deltas;\n"
    "#else\n"
    "        float tempY = floor(texcoordInPixels.y) + 0.5;\n"
    "        float yCoord = tempY / TextureSize.y;\n"
    "        float dy = texcoordInPixels.y - tempY;\n"
    "        float scanLineWeight = CalcScanLine(dy);\n"
    "        float signY = sign(dy);\n"
    "        dy = dy * dy;\n"
    "        dy = dy * dy;\n"
    "        dy *= 8.0;\n"
    "        dy /= TextureSize.y;\n"
    "        dy *= signY;\n"
    "        vec2 tc = vec2(texcoord.x, yCoord + dy);\n"
    "#endif\n"
    "\n"
    "        vec3 colour = texture2D(Texture, tc).rgb;\n"
    "\n"
    "#if defined(SCANLINES)\n"
    "#if defined(GAMMA)\n"
    "#if defined(FAKE_GAMMA)\n"
    "        colour = colour * colour;\n"
    "#else\n"
    "        colour = pow(colour, vec3(INPUT_GAMMA));\n"
    "#endif\n"
    "#endif\n"
    "        scanLineWeight *= BLOOM_FACTOR;\n"
    "        colour *= scanLineWeight;\n"
    "\n"
    "#if defined(GAMMA)\n"
    "#if defined(FAKE_GAMMA)\n"
    "        colour = sqrt(colour);\n"
    "#else\n"
    "        colour = pow(colour, vec3(1.0/OUTPUT_GAMMA));\n"
    "#endif\n"
    "#endif\n"
    "#endif\n"
    "#if MASK_TYPE == 0\n"
    "        gl_FragColor = vec4(colour, 1.0);\n"
    "#else\n"
    "#if MASK_TYPE == 1\n"
    "        float whichMask = fract(gl_FragCoord.x * 0.5);\n"
    "        vec3 mask;\n"
    "        if (whichMask < 0.5)\n"
    "            mask = vec3(MASK_BRIGHTNESS, 1.0, MASK_BRIGHTNESS);\n"
    "        else\n"
    "            mask = vec3(1.0, MASK_BRIGHTNESS, 1.0);\n"
    "#elif MASK_TYPE == 2\n"
    "        float whichMask = fract(gl_FragCoord.x * 0.3333333);\n"
    "        vec3 mask = vec3(MASK_BRIGHTNESS, MASK_BRIGHTNESS, MASK_BRIGHTNESS);\n"
    "        if (whichMask < 0.3333333)\n"
    "            mask.x = 1.0;\n"
    "        else if (whichMask < 0.6666666)\n"
    "            mask.y = 1.0;\n"
    "        else\n"
    "            mask.z = 1.0;\n"
    "#endif\n"
    "\n"
    "        gl_FragColor = vec4(colour * mask, 1.0);\n"
    "#endif\n"
    "    }\n"
    "}\n"
    "#endif\n"
    "\n";

static const char src_crt_lottes[] =
    "// PUBLIC DOMAIN CRT STYLED SCAN-LINE SHADER\n"
    "//\n"
    "//   by Timothy Lottes\n"
    "//\n"
    "// This is more along the style of a really good CGA arcade monitor.\n"
    "// With RGB inputs instead of NTSC.\n"
    "// The shadow mask example has the mask rotated 90 degrees for less chromatic aberration.\n"
    "//\n"
    "// Left it unoptimized to show the theory behind the algorithm.\n"
    "//\n"
    "// It is an example what I personally would want as a display option for pixel art games.\n"
    "// Please take and use, change, or whatever.\n"
    "\n"
    "// Parameter lines go here:\n"
    "#pragma parameter hardScan \"hardScan\" -8.0 -20.0 0.0 1.0\n"
    "#pragma parameter hardPix \"hardPix\" -3.0 -20.0 0.0 1.0\n"
    "#pragma parameter warpX \"warpX\" 0.031 0.0 0.125 0.01\n"
    "#pragma parameter warpY \"warpY\" 0.041 0.0 0.125 0.01\n"
    "#pragma parameter maskDark \"maskDark\" 0.5 0.0 2.0 0.1\n"
    "#pragma parameter maskLight \"maskLight\" 1.5 0.0 2.0 0.1\n"
    "#pragma parameter scaleInLinearGamma \"scaleInLinearGamma\" 1.0 0.0 1.0 1.0\n"
    "#pragma parameter shadowMask \"shadowMask\" 3.0 0.0 4.0 1.0\n"
    "#pragma parameter brightBoost \"brightness boost\" 1.0 0.0 2.0 0.05\n"
    "#pragma parameter hardBloomPix \"bloom-x soft\" -1.5 -2.0 -0.5 0.1\n"
    "#pragma parameter hardBloomScan \"bloom-y soft\" -2.0 -4.0 -1.0 0.1\n"
    "#pragma parameter bloomAmount \"bloom ammount\" 0.15 0.0 1.0 0.05\n"
    "#pragma parameter shape \"filter kernel shape\" 2.0 0.0 10.0 0.05\n"
    "\n"
    "#if defined(VERTEX)\n"
    "\n"
    "#if __VERSION__ >= 130\n"
    "#define COMPAT_VARYING out\n"
    "#define COMPAT_ATTRIBUTE in\n"
    "#define COMPAT_TEXTURE texture\n"
    "#else\n"
    "#define COMPAT_VARYING varying \n"
    "#define COMPAT_ATTRIBUTE attribute \n"
    "#define COMPAT_TEXTURE texture2D\n"
    "#endif\n"
    "\n"
    "#ifdef GL_ES\n"
    "#define COMPAT_PRECISION mediump\n"
    "#else\n"
    "#define COMPAT_PRECISION\n"
    "#endif\n"
    "\n"
    "COMPAT_ATTRIBUTE vec4 VertexCoord;\n"
    "COMPAT_ATTRIBUTE vec4 COLOR;\n"
    "COMPAT_ATTRIBUTE vec4 TexCoord;\n"
    "COMPAT_VARYING vec4 COL0;\n"
    "COMPAT_VARYING vec4 TEX0;\n"
    "\n"
    "uniform mat4 MVPMatrix;\n"
    "uniform COMPAT_PRECISION int FrameDirection;\n"
    "uniform COMPAT_PRECISION int FrameCount;\n"
    "uniform COMPAT_PRECISION vec2 OutputSize;\n"
    "uniform COMPAT_PRECISION vec2 TextureSize;\n"
    "uniform COMPAT_PRECISION vec2 InputSize;\n"
    "\n"
    "// vertex compatibility #defines\n"
    "#define vTexCoord TEX0.xy\n"
    "#define SourceSize vec4(TextureSize, 1.0 / TextureSize) //either TextureSize or InputSize\n"
    "#define outsize vec4(OutputSize, 1.0 / OutputSize)\n"
    "\n"
    "void main()\n"
    "{\n"
    "    gl_Position = MVPMatrix * VertexCoord;\n"
    "    TEX0.xy = TexCoord.xy;\n"
    "}\n"
    "\n"
    "#elif defined(FRAGMENT)\n"
    "\n"
    "#if __VERSION__ >= 130\n"
    "#define COMPAT_VARYING in\n"
    "#define COMPAT_TEXTURE texture\n"
    "out vec4 FragColor;\n"
    "#else\n"
    "#define COMPAT_VARYING varying\n"
    "#define FragColor gl_FragColor\n"
    "#define COMPAT_TEXTURE texture2D\n"
    "#endif\n"
    "\n"
    "#ifdef GL_ES\n"
    "#ifdef GL_FRAGMENT_PRECISION_HIGH\n"
    "precision highp float;\n"
    "#else\n"
    "precision mediump float;\n"
    "#endif\n"
    "#define COMPAT_PRECISION mediump\n"
    "#else\n"
    "#define COMPAT_PRECISION\n"
    "#endif\n"
    "\n"
    "uniform COMPAT_PRECISION int FrameDirection;\n"
    "uniform COMPAT_PRECISION int FrameCount;\n"
    "uniform COMPAT_PRECISION vec2 OutputSize;\n"
    "uniform COMPAT_PRECISION vec2 TextureSize;\n"
    "uniform COMPAT_PRECISION vec2 InputSize;\n"
    "uniform sampler2D Texture;\n"
    "COMPAT_VARYING vec4 TEX0;\n"
    "\n"
    "// fragment compatibility #defines\n"
    "#define Source Texture\n"
    "#define vTexCoord TEX0.xy\n"
    "\n"
    "#define SourceSize vec4(TextureSize, 1.0 / TextureSize) //either TextureSize or InputSize\n"
    "#define outsize vec4(OutputSize, 1.0 / OutputSize)\n"
    "\n"
    "#ifdef PARAMETER_UNIFORM\n"
    "// All parameter floats need to have COMPAT_PRECISION in front of them\n"
    "uniform COMPAT_PRECISION float hardScan;\n"
    "uniform COMPAT_PRECISION float hardPix;\n"
    "uniform COMPAT_PRECISION float warpX;\n"
    "uniform COMPAT_PRECISION float warpY;\n"
    "uniform COMPAT_PRECISION float maskDark;\n"
    "uniform COMPAT_PRECISION float maskLight;\n"
    "uniform COMPAT_PRECISION float scaleInLinearGamma;\n"
    "uniform COMPAT_PRECISION float shadowMask;\n"
    "uniform COMPAT_PRECISION float brightBoost;\n"
    "uniform COMPAT_PRECISION float hardBloomPix;\n"
    "uniform COMPAT_PRECISION float hardBloomScan;\n"
    "uniform COMPAT_PRECISION float bloomAmount;\n"
    "uniform COMPAT_PRECISION float shape;\n"
    "#else\n"
    "#define hardScan -8.0\n"
    "#define hardPix -3.0\n"
    "#define warpX 0.031\n"
    "#define warpY 0.041\n"
    "#define maskDark 0.5\n"
    "#define maskLight 1.5\n"
    "#define scaleInLinearGamma 1.0\n"
    "#define shadowMask 3.0\n"
    "#define brightBoost 1.0\n"
    "#define hardBloomPix -1.5\n"
    "#define hardBloomScan -2.0\n"
    "#define bloomAmount 0.15\n"
    "#define shape 2.0\n"
    "#endif\n"
    "\n"
    "//Uncomment to reduce instructions with simpler linearization\n"
    "//(fixes HD3000 Sandy Bridge IGP)\n"
    "//#define SIMPLE_LINEAR_GAMMA\n"
    "#define DO_BLOOM\n"
    "\n"
    "// ------------- //\n"
    "\n"
    "// sRGB to Linear.\n"
    "// Assuming using sRGB typed textures this should not be needed.\n"
    "#ifdef SIMPLE_LINEAR_GAMMA\n"
    "float ToLinear1(float c)\n"
    "{\n"
    "    return c;\n"
    "}\n"
    "vec3 ToLinear(vec3 c)\n"
    "{\n"
    "    return c;\n"
    "}\n"
    "vec3 ToSrgb(vec3 c)\n"
    "{\n"
    "    return pow(c, vec3(1.0 / 2.2));\n"
    "}\n"
    "#else\n"
    "float ToLinear1(float c)\n"
    "{\n"
    "    if (scaleInLinearGamma == 0.) \n"
    "        return c;\n"
    "    \n"
    "    return(c<=0.04045) ? c/12.92 : pow((c + 0.055)/1.055, 2.4);\n"
    "}\n"
    "\n"
    "vec3 ToLinear(vec3 c)\n"
    "{\n"
    "    if (scaleInLinearGamma==0.) \n"
    "        return c;\n"
    "    \n"
    "    return vec3(ToLinear1(c.r), ToLinear1(c.g), ToLinear1(c.b));\n"
    "}\n"
    "\n"
    "// Linear to sRGB.\n"
    "// Assuming using sRGB typed textures this should not be needed.\n"
    "float ToSrgb1(float c)\n"
    "{\n"
    "    if (scaleInLinearGamma == 0.) \n"
    "        return c;\n"
    "    \n"
    "    return(c<0.0031308 ? c*12.92 : 1.055*pow(c, 0.41666) - 0.055);\n"
    "}\n"
    "\n"
    "vec3 ToSrgb(vec3 c)\n"
    "{\n"
    "    if (scaleInLinearGamma == 0.) \n"
    "        return c;\n"
    "    \n"
    "    return vec3(ToSrgb1(c.r), ToSrgb1(c.g), ToSrgb1(c.b));\n"
    "}\n"
    "#endif\n"
    "\n"
    "// Nearest emulated sample given floating point position and texel offset.\n"
    "// Also zero's off screen.\n"
    "vec3 Fetch(vec2 pos,vec2 off){\n"
    "  pos=(floor(pos*SourceSize.xy+off)+vec2(0.5,0.5))/SourceSize.xy;\n"
    "#ifdef SIMPLE_LINEAR_GAMMA\n"
    "  return ToLinear(brightBoost * pow(COMPAT_TEXTURE(Source,pos.xy).rgb, vec3(2.2)));\n"
    "#else\n"
    "  return ToLinear(brightBoost * COMPAT_TEXTURE(Source,pos.xy).rgb);\n"
    "#endif\n"
    "}\n"
    "\n"
    "// Distance in emulated pixels to nearest texel.\n"
    "vec2 Dist(vec2 pos)\n"
    "{\n"
    "    pos = pos*SourceSize.xy;\n"
    "    \n"
    "    return -((pos - floor(pos)) - vec2(0.5));\n"
    "}\n"
    "    \n"
    "// 1D Gaussian.\n"
    "float Gaus(float pos, float scale)\n"
    "{\n"
    "    return exp2(scale*pow(abs(pos), shape));\n"
    "}\n"
    "\n"
    "// 3-tap Gaussian filter along horz line.\n"
    "vec3 Horz3(vec2 pos, float off)\n"
    "{\n"
    "    vec3 b    = Fetch(pos, vec2(-1.0, off));\n"
    "    vec3 c    = Fetch(pos, vec2( 0.0, off));\n"
    "    vec3 d    = Fetch(pos, vec2( 1.0, off));\n"
    "    float dst = Dist(pos).x;\n"
    "\n"
    "    // Convert distance to weight.\n"
    "    float scale = hardPix;\n"
    "    float wb = Gaus(dst-1.0,scale);\n"
    "    float wc = Gaus(dst+0.0,scale);\n"
    "    float wd = Gaus(dst+1.0,scale);\n"
    "\n"
    "    // Return filtered sample.\n"
    "    return (b*wb+c*wc+d*wd)/(wb+wc+wd);\n"
    "}\n"
    "\n"
    "// 5-tap Gaussian filter along horz line.\n"
    "vec3 Horz5(vec2 pos,float off){\n"
    "    vec3 a = Fetch(pos,vec2(-2.0, off));\n"
    "    vec3 b = Fetch(pos,vec2(-1.0, off));\n"
    "    vec3 c = Fetch(pos,vec2( 0.0, off));\n"
    "    vec3 d = Fetch(pos,vec2( 1.0, off));\n"
    "    vec3 e = Fetch(pos,vec2( 2.0, off));\n"
    "    \n"
    "    float dst = Dist(pos).x;\n"
    "    // Convert distance to weight.\n"
    "    float scale = hardPix;\n"
    "    float wa = Gaus(dst - 2.0, scale);\n"
    "    float wb = Gaus(dst - 1.0, scale);\n"
    "    float wc = Gaus(dst + 0.0, scale);\n"
    "    float wd = Gaus(dst + 1.0, scale);\n"
    "    float we = Gaus(dst + 2.0, scale);\n"
    "    \n"
    "    // Return filtered sample.\n"
    "    return (a*wa+b*wb+c*wc+d*wd+e*we)/(wa+wb+wc+wd+we);\n"
    "}\n"
    "  \n"
    "// 7-tap Gaussian filter along horz line.\n"
    "vec3 Horz7(vec2 pos,float off)\n"
    "{\n"
    "    vec3 a = Fetch(pos, vec2(-3.0, off));\n"
    "    vec3 b = Fetch(pos, vec2(-2.0, off));\n"
    "    vec3 c = Fetch(pos, vec2(-1.0, off));\n"
    "    vec3 d = Fetch(pos, vec2( 0.0, off));\n"
    "    vec3 e = Fetch(pos, vec2( 1.0, off));\n"
    "    vec3 f = Fetch(pos, vec2( 2.0, off));\n"
    "    vec3 g = Fetch(pos, vec2( 3.0, off));\n"
    "\n"
    "    float dst = Dist(pos).x;\n"
    "    // Convert distance to weight.\n"
    "    float scale = hardBloomPix;\n"
    "    float wa = Gaus(dst - 3.0, scale);\n"
    "    float wb = Gaus(dst - 2.0, scale);\n"
    "    float wc = Gaus(dst - 1.0, scale);\n"
    "    float wd = Gaus(dst + 0.0, scale);\n"
    "    float we = Gaus(dst + 1.0, scale);\n"
    "    float wf = Gaus(dst + 2.0, scale);\n"
    "    float wg = Gaus(dst + 3.0, scale);\n"
    "\n"
    "    // Return filtered sample.\n"
    "    return (a*wa+b*wb+c*wc+d*wd+e*we+f*wf+g*wg)/(wa+wb+wc+wd+we+wf+wg);\n"
    "}\n"
    "  \n"
    "// Return scanline weight.\n"
    "float Scan(vec2 pos, float off)\n"
    "{\n"
    "    float dst = Dist(pos).y;\n"
    "\n"
    "    return Gaus(dst + off, hardScan);\n"
    "}\n"
    "  \n"
    "// Return scanline weight for bloom.\n"
    "float BloomScan(vec2 pos, float off)\n"
    "{\n"
    "    float dst = Dist(pos).y;\n"
    "    \n"
    "    return Gaus(dst + off, hardBloomScan);\n"
    "}\n"
    "\n"
    "// Allow nearest three lines to effect pixel.\n"
    "vec3 Tri(vec2 pos)\n"
    "{\n"
    "    vec3 a = Horz3(pos,-1.0);\n"
    "    vec3 b = Horz5(pos, 0.0);\n"
    "    vec3 c = Horz3(pos, 1.0);\n"
    "    \n"
    "    float wa = Scan(pos,-1.0); \n"
    "    float wb = Scan(pos, 0.0);\n"
    "    float wc = Scan(pos, 1.0);\n"
    "    \n"
    "    return a*wa + b*wb + c*wc;\n"
    "}\n"
    "  \n"
    "// Small bloom.\n"
    "vec3 Bloom(vec2 pos)\n"
    "{\n"
    "    vec3 a = Horz5(pos,-2.0);\n"
    "    vec3 b = Horz7(pos,-1.0);\n"
    "    vec3 c = Horz7(pos, 0.0);\n"
    "    vec3 d = Horz7(pos, 1.0);\n"
    "    vec3 e = Horz5(pos, 2.0);\n"
    "\n"
    "    float wa = BloomScan(pos,-2.0);\n"
    "    float wb = BloomScan(pos,-1.0); \n"
    "    float wc = BloomScan(pos, 0.0);\n"
    "    float wd = BloomScan(pos, 1.0);\n"
    "    float we = BloomScan(pos, 2.0);\n"
    "\n"
    "    return a*wa+b*wb+c*wc+d*wd+e*we;\n"
    "}\n"
    "  \n"
    "// Distortion of scanlines, and end of screen alpha.\n"
    "vec2 Warp(vec2 pos)\n"
    "{\n"
    "    pos  = pos*2.0-1.0;    \n"
    "    pos *= vec2(1.0 + (pos.y*pos.y)*warpX, 1.0 + (pos.x*pos.x)*warpY);\n"
    "    \n"
    "    return pos*0.5 + 0.5;\n"
    "}\n"
    "  \n"
    "// Shadow mask.\n"
    "vec3 Mask(vec2 pos)\n"
    "{\n"
    "    vec3 mask = vec3(maskDark, maskDark, maskDark);\n"
    "  \n"
    "    // Very compressed TV style shadow mask.\n"
    "    if (shadowMask == 1.0) \n"
    "    {\n"
    "        float line = maskLight;\n"
    "        float odd = 0.0;\n"
    "        \n"
    "        if (fract(pos.x*0.166666666) < 0.5) odd = 1.0;\n"
    "        if (fract((pos.y + odd) * 0.5) < 0.5) line = maskDark;  \n"
    "        \n"
    "        pos.x = fract(pos.x*0.333333333);\n"
    "\n"
    "        if      (pos.x < 0.333) mask.r = maskLight;\n"
    "        else if (pos.x < 0.666) mask.g = maskLight;\n"
    "        else                    mask.b = maskLight;\n"
    "        mask*=line;  \n"
    "    } \n"
    "\n"
    "    // Aperture-grille.\n"
    "    else if (shadowMask == 2.0) \n"
    "    {\n"
    "        pos.x = fract(pos.x*0.333333333);\n"
    "\n"
    "        if      (pos.x < 0.333) mask.r = maskLight;\n"
    "        else if (pos.x < 0.666) mask.g = maskLight;\n"
    "        else                    mask.b = maskLight;\n"
    "    } \n"
    "\n"
    "    // Stretched VGA style shadow mask (same as prior shaders).\n"
    "    else if (shadowMask == 3.0) \n"
    "    {\n"
    "        pos.x += pos.y*3.0;\n"
    "        pos.x  = fract(pos.x*0.166666666);\n"
    "\n"
    "        if      (pos.x < 0.333) mask.r = maskLight;\n"
    "        else if (pos.x < 0.666) mask.g = maskLight;\n"
    "        else                    mask.b = maskLight;\n"
    "    }\n"
    "\n"
    "    // VGA style shadow mask.\n"
    "    else if (shadowMask == 4.0) \n"
    "    {\n"
    "        pos.xy  = floor(pos.xy*vec2(1.0, 0.5));\n"
    "        pos.x  += pos.y*3.0;\n"
    "        pos.x   = fract(pos.x*0.166666666);\n"
    "\n"
    "        if      (pos.x < 0.333) mask.r = maskLight;\n"
    "        else if (pos.x < 0.666) mask.g = maskLight;\n"
    "        else                    mask.b = maskLight;\n"
    "    }\n"
    "\n"
    "    return mask;\n"
    "}\n"
    "\n"
    "void main()\n"
    "{\n"
    "    vec2 pos = Warp(TEX0.xy*(TextureSize.xy/InputSize.xy))*(InputSize.xy/TextureSize.xy);\n"
    "    vec3 outColor = Tri(pos);\n"
    "\n"
    "#ifdef DO_BLOOM\n"
    "    //Add Bloom\n"
    "    outColor.rgb += Bloom(pos)*bloomAmount;\n"
    "#endif\n"
    "\n"
    "    if (shadowMask > 0.0)\n"
    "        outColor.rgb *= Mask(gl_FragCoord.xy * 1.000001);\n"
    "    \n"
    "#ifdef GL_ES    /* TODO/FIXME - hacky clamp fix */\n"
    "    vec2 bordertest = (pos);\n"
    "    if ( bordertest.x > 0.0001 && bordertest.x < 0.9999 && bordertest.y > 0.0001 && bordertest.y < 0.9999)\n"
    "        outColor.rgb = outColor.rgb;\n"
    "    else\n"
    "        outColor.rgb = vec3(0.0);\n"
    "#endif\n"
    "    FragColor = vec4(ToSrgb(outColor.rgb), 1.0);\n"
    "} \n"
    "#endif\n"
    "\n";

static const char src_crt_geom[] =
    "/*\n"
    "    CRT-interlaced\n"
    "\n"
    "    Copyright (C) 2010-2012 cgwg, Themaister and DOLLS\n"
    "\n"
    "    This program is free software; you can redistribute it and/or modify it\n"
    "    under the terms of the GNU General Public License as published by the Free\n"
    "    Software Foundation; either version 2 of the License, or (at your option)\n"
    "    any later version.\n"
    "\n"
    "    (cgwg gave their consent to have the original version of this shader\n"
    "    distributed under the GPL in this message:\n"
    "\n"
    "        http://board.byuu.org/viewtopic.php?p=26075#p26075\n"
    "\n"
    "        \"Feel free to distribute my shaders under the GPL. After all, the\n"
    "        barrel distortion code was taken from the Curvature shader, which is\n"
    "        under the GPL.\"\n"
    "    )\n"
    "    This shader variant is pre-configured with screen curvature\n"
    "*/\n"
    "\n"
    "#pragma parameter CRTgamma \"CRTGeom Target Gamma\" 2.4 0.1 5.0 0.1\n"
    "#pragma parameter INV \"Inverse Gamma/CRT-Geom Gamma out\" 0.0 0.0 1.0 1.0\n"
    "#pragma parameter monitorgamma \"CRTGeom Monitor Gamma\" 2.2 0.1 5.0 0.1\n"
    "#pragma parameter d \"CRTGeom Distance\" 1.6 0.1 3.0 0.1\n"
    "#pragma parameter CURVATURE \"CRTGeom Curvature Toggle\" 1.0 0.0 1.0 1.0\n"
    "#pragma parameter R \"CRTGeom Curvature Radius\" 2.0 0.1 10.0 0.1\n"
    "#pragma parameter cornersize \"CRTGeom Corner Size\" 0.03 0.001 1.0 0.005\n"
    "#pragma parameter cornersmooth \"CRTGeom Corner Smoothness\" 1000.0 80.0 2000.0 100.0\n"
    "#pragma parameter x_tilt \"CRTGeom Horizontal Tilt\" 0.0 -0.5 0.5 0.05\n"
    "#pragma parameter y_tilt \"CRTGeom Vertical Tilt\" 0.0 -0.5 0.5 0.05\n"
    "#pragma parameter overscan_x \"CRTGeom Horiz. Overscan %\" 100.0 -125.0 125.0 1.0\n"
    "#pragma parameter overscan_y \"CRTGeom Vert. Overscan %\" 100.0 -125.0 125.0 1.0\n"
    "#pragma parameter DOTMASK \"CRTGeom Dot Mask Strength\" 0.3 0.0 1.0 0.1\n"
    "#pragma parameter SHARPER \"CRTGeom Sharpness\" 1.0 1.0 3.0 1.0\n"
    "#pragma parameter scanline_weight \"CRTGeom Scanline Weight\" 0.3 0.1 0.5 0.05\n"
    "#pragma parameter lum \"CRTGeom Luminance\" 0.0 0.0 1.0 0.01\n"
    "#pragma parameter interlace_detect \"CRTGeom Interlacing Simulation\" 1.0 0.0 1.0 1.0\n"
    "#pragma parameter SATURATION \"CRTGeom Saturation\" 1.0 0.0 2.0 0.05\n"
    "\n"
    "#ifndef PARAMETER_UNIFORM\n"
    "#define CRTgamma 2.4\n"
    "#define monitorgamma 2.2\n"
    "#define d 1.6\n"
    "#define CURVATURE 1.0\n"
    "#define R 2.0\n"
    "#define cornersize 0.03\n"
    "#define cornersmooth 1000.0\n"
    "#define x_tilt 0.0\n"
    "#define y_tilt 0.0\n"
    "#define overscan_x 100.0\n"
    "#define overscan_y 100.0\n"
    "#define DOTMASK 0.3\n"
    "#define SHARPER 1.0\n"
    "#define scanline_weight 0.3\n"
    "#define lum 0.0\n"
    "#define interlace_detect 1.0\n"
    "#define SATURATION 1.0\n"
    "#define INV 1.0\n"
    "#endif\n"
    "\n"
    "#if defined(VERTEX)\n"
    "\n"
    "#if __VERSION__ >= 130\n"
    "#define COMPAT_VARYING out\n"
    "#define COMPAT_ATTRIBUTE in\n"
    "#define COMPAT_TEXTURE texture\n"
    "#else\n"
    "#define COMPAT_VARYING varying \n"
    "#define COMPAT_ATTRIBUTE attribute \n"
    "#define COMPAT_TEXTURE texture2D\n"
    "#endif\n"
    "\n"
    "#ifdef GL_ES\n"
    "#define COMPAT_PRECISION mediump\n"
    "#else\n"
    "#define COMPAT_PRECISION\n"
    "#endif\n"
    "\n"
    "COMPAT_ATTRIBUTE vec4 VertexCoord;\n"
    "COMPAT_ATTRIBUTE vec4 COLOR;\n"
    "COMPAT_ATTRIBUTE vec4 TexCoord;\n"
    "COMPAT_VARYING vec4 COL0;\n"
    "COMPAT_VARYING vec4 TEX0;\n"
    "\n"
    "vec4 _oPosition1; \n"
    "uniform mat4 MVPMatrix;\n"
    "uniform COMPAT_PRECISION int FrameDirection;\n"
    "uniform COMPAT_PRECISION int FrameCount;\n"
    "uniform COMPAT_PRECISION vec2 OutputSize;\n"
    "uniform COMPAT_PRECISION vec2 TextureSize;\n"
    "uniform COMPAT_PRECISION vec2 InputSize;\n"
    "\n"
    "COMPAT_VARYING vec2 overscan;\n"
    "COMPAT_VARYING vec2 aspect;\n"
    "COMPAT_VARYING vec3 stretch;\n"
    "COMPAT_VARYING vec2 sinangle;\n"
    "COMPAT_VARYING vec2 cosangle;\n"
    "COMPAT_VARYING vec2 one;\n"
    "COMPAT_VARYING float mod_factor;\n"
    "COMPAT_VARYING vec2 ilfac;\n"
    "\n"
    "#ifdef PARAMETER_UNIFORM\n"
    "uniform COMPAT_PRECISION float CRTgamma;\n"
    "uniform COMPAT_PRECISION float monitorgamma;\n"
    "uniform COMPAT_PRECISION float d;\n"
    "uniform COMPAT_PRECISION float CURVATURE;\n"
    "uniform COMPAT_PRECISION float R;\n"
    "uniform COMPAT_PRECISION float cornersize;\n"
    "uniform COMPAT_PRECISION float cornersmooth;\n"
    "uniform COMPAT_PRECISION float x_tilt;\n"
    "uniform COMPAT_PRECISION float y_tilt;\n"
    "uniform COMPAT_PRECISION float overscan_x;\n"
    "uniform COMPAT_PRECISION float overscan_y;\n"
    "uniform COMPAT_PRECISION float DOTMASK;\n"
    "uniform COMPAT_PRECISION float SHARPER;\n"
    "uniform COMPAT_PRECISION float scanline_weight;\n"
    "uniform COMPAT_PRECISION float lum;\n"
    "uniform COMPAT_PRECISION float interlace_detect;\n"
    "uniform COMPAT_PRECISION float SATURATION;\n"
    "#endif\n"
    "\n"
    "#define FIX(c) max(abs(c), 1e-5);\n"
    "\n"
    "float intersect(vec2 xy)\n"
    "        {\n"
    "    float A = dot(xy,xy)+d*d;\n"
    "    float B = 2.0*(R*(dot(xy,sinangle)-d*cosangle.x*cosangle.y)-d*d);\n"
    "    float C = d*d + 2.0*R*d*cosangle.x*cosangle.y;\n"
    "    return (-B-sqrt(B*B-4.0*A*C))/(2.0*A);\n"
    "        }\n"
    "\n"
    "vec2 bkwtrans(vec2 xy)\n"
    "        {\n"
    "    float c = intersect(xy);\n"
    "    vec2 point = vec2(c)*xy;\n"
    "    point -= vec2(-R)*sinangle;\n"
    "    point /= vec2(R);\n"
    "    vec2 tang = sinangle/cosangle;\n"
    "    vec2 poc = point/cosangle;\n"
    "    float A = dot(tang,tang)+1.0;\n"
    "    float B = -2.0*dot(poc,tang);\n"
    "    float C = dot(poc,poc)-1.0;\n"
    "    float a = (-B+sqrt(B*B-4.0*A*C))/(2.0*A);\n"
    "    vec2 uv = (point-a*sinangle)/cosangle;\n"
    "    float r = R*acos(a);\n"
    "    return uv*r/sin(r/R);\n"
    "        }\n"
    "\n"
    "vec2 fwtrans(vec2 uv)\n"
    "        {\n"
    "    float r = FIX(sqrt(dot(uv,uv)));\n"
    "    uv *= sin(r/R)/r;\n"
    "    float x = 1.0-cos(r/R);\n"
    "    float D = d/R + x*cosangle.x*cosangle.y+dot(uv,sinangle);\n"
    "    return d*(uv*cosangle-x*sinangle)/D;\n"
    "        }\n"
    "\n"
    "vec3 maxscale()\n"
    "        {\n"
    "    vec2 c = bkwtrans(-R * sinangle / (1.0 + R/d*cosangle.x*cosangle.y));\n"
    "    vec2 a = vec2(0.5,0.5)*aspect;\n"
    "    vec2 lo = vec2(fwtrans(vec2(-a.x,c.y)).x, fwtrans(vec2(c.x,-a.y)).y)/aspect;\n"
    "    vec2 hi = vec2(fwtrans(vec2(+a.x,c.y)).x, fwtrans(vec2(c.x,+a.y)).y)/aspect;\n"
    "    return vec3((hi+lo)*aspect*0.5,max(hi.x-lo.x,hi.y-lo.y));\n"
    "        }\n"
    "\n"
    "void main()\n"
    "{\n"
    "// START of parameters\n"
    "\n"
    "// gamma of simulated CRT\n"
    "//    CRTgamma = 1.8;\n"
    "// gamma of display monitor (typically 2.2 is correct)\n"
    "//    monitorgamma = 2.2;\n"
    "// overscan (e.g. 1.02 for 2% overscan)\n"
    "    overscan = vec2(1.00,1.00);\n"
    "// aspect ratio\n"
    "    aspect = vec2(1.0, 0.75);\n"
    "// lengths are measured in units of (approximately) the width\n"
    "// of the monitor simulated distance from viewer to monitor\n"
    "//    d = 2.0;\n"
    "// radius of curvature\n"
    "//    R = 1.5;\n"
    "// tilt angle in radians\n"
    "// (behavior might be a bit wrong if both components are\n"
    "// nonzero)\n"
    "    const vec2 angle = vec2(0.0,0.0);\n"
    "// size of curved corners\n"
    "//    cornersize = 0.03;\n"
    "// border smoothness parameter\n"
    "// decrease if borders are too aliased\n"
    "//    cornersmooth = 1000.0;\n"
    "\n"
    "// END of parameters\n"
    "\n"
    "    vec4 _oColor;\n"
    "    vec2 _otexCoord;\n"
    "    gl_Position = VertexCoord.x * MVPMatrix[0] + VertexCoord.y * MVPMatrix[1] + VertexCoord.z * MVPMatrix[2] + VertexCoord.w * MVPMatrix[3];\n"
    "    _oPosition1 = gl_Position;\n"
    "    _oColor = COLOR;\n"
    "    _otexCoord = TexCoord.xy*1.0001;\n"
    "    COL0 = COLOR;\n"
    "    TEX0.xy = TexCoord.xy*1.0001;\n"
    "\n"
    "// Precalculate a bunch of useful values we'll need in the fragment\n"
    "// shader.\n"
    "    sinangle = sin(vec2(x_tilt, y_tilt)) + vec2(0.001);//sin(vec2(max(abs(x_tilt), 1e-3), max(abs(y_tilt), 1e-3)));\n"
    "    cosangle = cos(vec2(x_tilt, y_tilt)) + vec2(0.001);//cos(vec2(max(abs(x_tilt), 1e-3), max(abs(y_tilt), 1e-3)));\n"
    "    stretch = maxscale();\n"
    "\n"
    "    ilfac = vec2(1.0,clamp(floor(InputSize.y/200.0), 1.0, 2.0));\n"
    "\n"
    "// The size of one texel, in texture-coordinates.\n"
    "    vec2 sharpTextureSize = vec2(SHARPER * TextureSize.x, TextureSize.y);\n"
    "    one = ilfac / sharpTextureSize;\n"
    "\n"
    "// Resulting X pixel-coordinate of the pixel we're drawing.\n"
    "    mod_factor = TexCoord.x * TextureSize.x * OutputSize.x / InputSize.x;\n"
    "\n"
    "}\n"
    "\n"
    "#elif defined(FRAGMENT)\n"
    "\n"
    "#if __VERSION__ >= 130\n"
    "#define COMPAT_VARYING in\n"
    "#define COMPAT_TEXTURE texture\n"
    "out vec4 FragColor;\n"
    "#else\n"
    "#define COMPAT_VARYING varying\n"
    "#define FragColor gl_FragColor\n"
    "#define COMPAT_TEXTURE texture2D\n"
    "#endif\n"
    "\n"
    "#ifdef GL_ES\n"
    "#ifdef GL_FRAGMENT_PRECISION_HIGH\n"
    "precision highp float;\n"
    "#else\n"
    "precision mediump float;\n"
    "#endif\n"
    "#define COMPAT_PRECISION mediump\n"
    "#else\n"
    "#define COMPAT_PRECISION\n"
    "#endif\n"
    "\n"
    "struct output_dummy {\n"
    "    vec4 _color;\n"
    "};\n"
    "\n"
    "uniform COMPAT_PRECISION int FrameDirection;\n"
    "uniform COMPAT_PRECISION int FrameCount;\n"
    "uniform COMPAT_PRECISION vec2 OutputSize;\n"
    "uniform COMPAT_PRECISION vec2 TextureSize;\n"
    "uniform COMPAT_PRECISION vec2 InputSize;\n"
    "uniform sampler2D Texture;\n"
    "COMPAT_VARYING vec4 TEX0;\n"
    "\n"
    "// Comment the next line to disable interpolation in linear gamma (and\n"
    "// gain speed).\n"
    "    #define LINEAR_PROCESSING\n"
    "\n"
    "// Enable screen curvature.\n"
    "//        #define CURVATURE\n"
    "\n"
    "// Enable 3x oversampling of the beam profile\n"
    "        #define OVERSAMPLE\n"
    "\n"
    "// Use the older, purely gaussian beam profile\n"
    "        //#define USEGAUSSIAN\n"
    "\n"
    "// Macros.\n"
    "#define FIX(c) max(abs(c), 1e-5);\n"
    "#define PI 3.141592653589\n"
    "\n"
    "#ifdef LINEAR_PROCESSING\n"
    "#       define TEX2D(c) pow(COMPAT_TEXTURE(Texture, (c)), vec4(CRTgamma))\n"
    "#else\n"
    "#       define TEX2D(c) COMPAT_TEXTURE(Texture, (c))\n"
    "#endif\n"
    "\n"
    "COMPAT_VARYING vec2 one;\n"
    "COMPAT_VARYING float mod_factor;\n"
    "COMPAT_VARYING vec2 ilfac;\n"
    "COMPAT_VARYING vec2 overscan;\n"
    "COMPAT_VARYING vec2 aspect;\n"
    "COMPAT_VARYING vec3 stretch;\n"
    "COMPAT_VARYING vec2 sinangle;\n"
    "COMPAT_VARYING vec2 cosangle;\n"
    "\n"
    "#ifdef PARAMETER_UNIFORM\n"
    "uniform COMPAT_PRECISION float CRTgamma;\n"
    "uniform COMPAT_PRECISION float monitorgamma;\n"
    "uniform COMPAT_PRECISION float d;\n"
    "uniform COMPAT_PRECISION float CURVATURE;\n"
    "uniform COMPAT_PRECISION float R;\n"
    "uniform COMPAT_PRECISION float cornersize;\n"
    "uniform COMPAT_PRECISION float cornersmooth;\n"
    "uniform COMPAT_PRECISION float x_tilt;\n"
    "uniform COMPAT_PRECISION float y_tilt;\n"
    "uniform COMPAT_PRECISION float overscan_x;\n"
    "uniform COMPAT_PRECISION float overscan_y;\n"
    "uniform COMPAT_PRECISION float DOTMASK;\n"
    "uniform COMPAT_PRECISION float SHARPER;\n"
    "uniform COMPAT_PRECISION float scanline_weight;\n"
    "uniform COMPAT_PRECISION float lum;\n"
    "uniform COMPAT_PRECISION float interlace_detect;\n"
    "uniform COMPAT_PRECISION float SATURATION;\n"
    "uniform COMPAT_PRECISION float INV;\n"
    "#endif\n"
    "\n"
    "float intersect(vec2 xy)\n"
    "        {\n"
    "    float A = dot(xy,xy)+d*d;\n"
    "    float B = 2.0*(R*(dot(xy,sinangle)-d*cosangle.x*cosangle.y)-d*d);\n"
    "    float C = d*d + 2.0*R*d*cosangle.x*cosangle.y;\n"
    "    return (-B-sqrt(B*B-4.0*A*C))/(2.0*A);\n"
    "        }\n"
    "\n"
    "vec2 bkwtrans(vec2 xy)\n"
    "        {\n"
    "    float c = intersect(xy);\n"
    "    vec2 point = vec2(c)*xy;\n"
    "    point -= vec2(-R)*sinangle;\n"
    "    point /= vec2(R);\n"
    "    vec2 tang = sinangle/cosangle;\n"
    "    vec2 poc = point/cosangle;\n"
    "    float A = dot(tang,tang)+1.0;\n"
    "    float B = -2.0*dot(poc,tang);\n"
    "    float C = dot(poc,poc)-1.0;\n"
    "    float a = (-B+sqrt(B*B-4.0*A*C))/(2.0*A);\n"
    "    vec2 uv = (point-a*sinangle)/cosangle;\n"
    "    float r = FIX(R*acos(a));\n"
    "    return uv*r/sin(r/R);\n"
    "        }\n"
    "\n"
    "vec2 transform(vec2 coord)\n"
    "        {\n"
    "    coord *= TextureSize / InputSize;\n"
    "    coord = (coord-vec2(0.5))*aspect*stretch.z+stretch.xy;\n"
    "    return (bkwtrans(coord)/vec2(overscan_x / 100.0, overscan_y / 100.0)/aspect+vec2(0.5)) * InputSize / TextureSize;\n"
    "        }\n"
    "\n"
    "float corner(vec2 coord)\n"
    "        {\n"
    "    coord *= TextureSize / InputSize;\n"
    "    coord = (coord - vec2(0.5)) * vec2(overscan_x / 100.0, overscan_y / 100.0) + vec2(0.5);\n"
    "    coord = min(coord, vec2(1.0)-coord) * aspect;\n"
    "    vec2 cdist = vec2(cornersize);\n"
    "    coord = (cdist - min(coord,cdist));\n"
    "    float dist = sqrt(dot(coord,coord));\n"
    "    return clamp((cdist.x-dist)*cornersmooth,0.0, 1.0)*1.0001;\n"
    "        }\n"
    "\n"
    "// Calculate the influence of a scanline on the current pixel.\n"
    "//\n"
    "// 'distance' is the distance in texture coordinates from the current\n"
    "// pixel to the scanline in question.\n"
    "// 'color' is the colour of the scanline at the horizontal location of\n"
    "// the current pixel.\n"
    "vec4 scanlineWeights(float distance, vec4 color)\n"
    "        {\n"
    "    // \"wid\" controls the width of the scanline beam, for each RGB\n"
    "    // channel The \"weights\" lines basically specify the formula\n"
    "    // that gives you the profile of the beam, i.e. the intensity as\n"
    "    // a function of distance from the vertical center of the\n"
    "    // scanline. In this case, it is gaussian if width=2, and\n"
    "    // becomes nongaussian for larger widths. Ideally this should\n"
    "    // be normalized so that the integral across the beam is\n"
    "    // independent of its width. That is, for a narrower beam\n"
    "    // \"weights\" should have a higher peak at the center of the\n"
    "    // scanline than for a wider beam.\n"
    "#ifdef USEGAUSSIAN\n"
    "    vec4 wid = 0.3 + 0.1 * pow(color, vec4(3.0));\n"
    "    vec4 weights = vec4(distance / wid);\n"
    "    return (lum + 0.4) * exp(-weights * weights) / wid;\n"
    "#else\n"
    "    vec4 wid = 2.0 + 2.0 * pow(color, vec4(4.0));\n"
    "    vec4 weights = vec4(distance / scanline_weight);\n"
    "    return (lum + 1.4) * exp(-pow(weights * inversesqrt(0.5 * wid), wid)) / (0.6 + 0.2 * wid);\n"
    "#endif\n"
    "        }\n"
    "\n"
    "vec3 saturation (vec3 textureColor)\n"
    "{\n"
    "    float lum=length(textureColor)*0.5775;\n"
    "\n"
    "    vec3 luminanceWeighting = vec3(0.3,0.6,0.1);\n"
    "    if (lum<0.5) luminanceWeighting.rgb=(luminanceWeighting.rgb*luminanceWeighting.rgb)+(luminanceWeighting.rgb*luminanceWeighting.rgb);\n"
    "\n"
    "    float luminance = dot(textureColor, luminanceWeighting);\n"
    "    vec3 greyScaleColor = vec3(luminance);\n"
    "\n"
    "    vec3 res = vec3(mix(greyScaleColor, textureColor, SATURATION));\n"
    "    return res;\n"
    "}\n"
    "\n"
    "#define pwr vec3(1.0/((-0.7*(1.0-scanline_weight)+1.0)*(-0.5*DOTMASK+1.0))-1.25)\n"
    "\n"
    "\n"
    "// Returns gamma corrected output, compensated for scanline+mask embedded gamma\n"
    "vec3 inv_gamma(vec3 col, vec3 power)\n"
    "{\n"
    "    vec3 cir  = col-1.0;\n"
    "         cir *= cir;\n"
    "         col  = mix(sqrt(col),sqrt(1.0-cir),power);\n"
    "    return col;\n"
    "}\n"
    "\n"
    "void main()\n"
    "{\n"
    "// Here's a helpful diagram to keep in mind while trying to\n"
    "// understand the code:\n"
    "//\n"
    "//  |      |      |      |      |\n"
    "// -------------------------------\n"
    "//  |      |      |      |      |\n"
    "//  |  01  |  11  |  21  |  31  | <-- current scanline\n"
    "//  |      | @    |      |      |\n"
    "// -------------------------------\n"
    "//  |      |      |      |      |\n"
    "//  |  02  |  12  |  22  |  32  | <-- next scanline\n"
    "//  |      |      |      |      |\n"
    "// -------------------------------\n"
    "//  |      |      |      |      |\n"
    "//\n"
    "// Each character-cell represents a pixel on the output\n"
    "// surface, \"@\" represents the current pixel (always somewhere\n"
    "// in the bottom half of the current scan-line, or the top-half\n"
    "// of the next scanline). The grid of lines represents the\n"
    "// edges of the texels of the underlying texture.\n"
    "\n"
    "// Texture coordinates of the texel containing the active pixel.\n"
    "    vec2 xy = (CURVATURE > 0.5) ? transform(TEX0.xy) : TEX0.xy;\n"
    "\n"
    "    float cval = corner(xy);\n"
    "\n"
    "// Of all the pixels that are mapped onto the texel we are\n"
    "// currently rendering, which pixel are we currently rendering?\n"
    "    vec2 ilvec = vec2(0.0,ilfac.y * interlace_detect > 1.5 ? mod(float(FrameCount),2.0) : 0.0);\n"
    "    vec2 ratio_scale = (xy * TextureSize - vec2(0.5) + ilvec)/ilfac;\n"
    "#ifdef OVERSAMPLE\n"
    "    float filter_ = InputSize.y/OutputSize.y;//fwidth(ratio_scale.y);\n"
    "#endif\n"
    "    vec2 uv_ratio = fract(ratio_scale);\n"
    "\n"
    "// Snap to the center of the underlying texel.\n"
    "    xy = (floor(ratio_scale)*ilfac + vec2(0.5) - ilvec) / TextureSize;\n"
    "\n"
    "// Calculate Lanczos scaling coefficients describing the effect\n"
    "// of various neighbour texels in a scanline on the current\n"
    "// pixel.\n"
    "    vec4 coeffs = PI * vec4(1.0 + uv_ratio.x, uv_ratio.x, 1.0 - uv_ratio.x, 2.0 - uv_ratio.x);\n"
    "\n"
    "// Prevent division by zero.\n"
    "    coeffs = FIX(coeffs);\n"
    "\n"
    "// Lanczos2 kernel.\n"
    "    coeffs = 2.0 * sin(coeffs) * sin(coeffs / 2.0) / (coeffs * coeffs);\n"
    "\n"
    "// Normalize.\n"
    "    coeffs /= dot(coeffs, vec4(1.0));\n"
    "\n"
    "// Calculate the effective colour of the current and next\n"
    "// scanlines at the horizontal location of the current pixel,\n"
    "// using the Lanczos coefficients above.\n"
    "    vec4 col  = clamp(mat4(\n"
    "                        TEX2D(xy + vec2(-one.x, 0.0)),\n"
    "                        TEX2D(xy),\n"
    "                        TEX2D(xy + vec2(one.x, 0.0)),\n"
    "                        TEX2D(xy + vec2(2.0 * one.x, 0.0))) * coeffs,\n"
    "                        0.0, 1.0);\n"
    "        vec4 col2 = clamp(mat4(\n"
    "                        TEX2D(xy + vec2(-one.x, one.y)),\n"
    "                        TEX2D(xy + vec2(0.0, one.y)),\n"
    "                        TEX2D(xy + one),\n"
    "                        TEX2D(xy + vec2(2.0 * one.x, one.y))) * coeffs,\n"
    "                        0.0, 1.0);\n"
    "\n"
    "#ifndef LINEAR_PROCESSING\n"
    "    col  = pow(col , vec4(CRTgamma));\n"
    "    col2 = pow(col2, vec4(CRTgamma));\n"
    "#endif\n"
    "\n"
    "// Calculate the influence of the current and next scanlines on\n"
    "// the current pixel.\n"
    "    vec4 weights  = scanlineWeights(uv_ratio.y, col);\n"
    "    vec4 weights2 = scanlineWeights(1.0 - uv_ratio.y, col2);\n"
    "#ifdef OVERSAMPLE\n"
    "    uv_ratio.y =uv_ratio.y+1.0/3.0*filter_;\n"
    "    weights = (weights+scanlineWeights(uv_ratio.y, col))/3.0;\n"
    "    weights2=(weights2+scanlineWeights(abs(1.0-uv_ratio.y), col2))/3.0;\n"
    "    uv_ratio.y =uv_ratio.y-2.0/3.0*filter_;\n"
    "    weights=weights+scanlineWeights(abs(uv_ratio.y), col)/3.0;\n"
    "    weights2=weights2+scanlineWeights(abs(1.0-uv_ratio.y), col2)/3.0;\n"
    "#endif\n"
    "\n"
    "    vec3 mul_res  = (col * weights + col2 * weights2).rgb * vec3(cval);\n"
    "\n"
    "// dot-mask emulation:\n"
    "// Output pixels are alternately tinted green and magenta.\n"
    "vec3 dotMaskWeights = mix(\n"
    "    vec3(1.0, 1.0 - DOTMASK, 1.0),\n"
    "    vec3(1.0 - DOTMASK, 1.0, 1.0 - DOTMASK),\n"
    "    floor(mod(mod_factor, 2.0))\n"
    "        );\n"
    "\n"
    "    mul_res *= dotMaskWeights;\n"
    "\n"
    "// Convert the image gamma for display on our output device.\n"
    "if (INV == 1.0){ mul_res = inv_gamma(mul_res,pwr);} \n"
    "    else mul_res = pow(mul_res, vec3(1.0/monitorgamma));\n"
    "        \n"
    "        mul_res = saturation(mul_res);\n"
    "\n"
    "\n"
    "\n"
    "// Color the texel.\n"
    "    output_dummy _OUT;\n"
    "    _OUT._color = vec4(mul_res, 1.0);\n"
    "    FragColor = _OUT._color;\n"
    "    return;\n"
    "} \n"
    "#endif\n"
    "\n";

static const char src_fxaa[] =
    "/*\n"
    "    fxaa -- fast approximate anti-aliasing, for Doom Legacy Arcade.\n"
    "    Written for this project from Timothy Lottes' published FXAA method\n"
    "    (the short \"console\" form): find the edge direction from the luma of the\n"
    "    four diagonal neighbours, then blur along it.\n"
    "\n"
    "    This program is free software; you can redistribute it and/or modify it\n"
    "    under the terms of the GNU General Public License as published by the Free\n"
    "    Software Foundation; either version 2 of the License, or (at your option)\n"
    "    any later version.\n"
    "\n"
    "    Runs on the full-size frame.  Needs linear sampling.\n"
    "*/\n"
    "\n"
    "#if defined(VERTEX)\n"
    "attribute vec4 VertexCoord;\n"
    "attribute vec4 TexCoord;\n"
    "varying vec2 uv;\n"
    "uniform mat4 MVPMatrix;\n"
    "void main()\n"
    "{\n"
    "    gl_Position = MVPMatrix * VertexCoord;\n"
    "    uv = TexCoord.xy;\n"
    "}\n"
    "\n"
    "#elif defined(FRAGMENT)\n"
    "uniform sampler2D Texture;\n"
    "uniform vec2 TextureSize;\n"
    "varying vec2 uv;\n"
    "\n"
    "#define REDUCE_MIN  (1.0/128.0)\n"
    "#define REDUCE_MUL  (1.0/8.0)\n"
    "#define SPAN_MAX    8.0\n"
    "\n"
    "void main()\n"
    "{\n"
    "    vec2 px = 1.0 / TextureSize;\n"
    "    vec3 luma = vec3(0.299, 0.587, 0.114);\n"
    "    vec3 rgbNW = texture2D(Texture, uv + vec2(-1.0, -1.0) * px).rgb;\n"
    "    vec3 rgbNE = texture2D(Texture, uv + vec2( 1.0, -1.0) * px).rgb;\n"
    "    vec3 rgbSW = texture2D(Texture, uv + vec2(-1.0,  1.0) * px).rgb;\n"
    "    vec3 rgbSE = texture2D(Texture, uv + vec2( 1.0,  1.0) * px).rgb;\n"
    "    vec3 rgbM  = texture2D(Texture, uv).rgb;\n"
    "    float lNW = dot(rgbNW, luma);\n"
    "    float lNE = dot(rgbNE, luma);\n"
    "    float lSW = dot(rgbSW, luma);\n"
    "    float lSE = dot(rgbSE, luma);\n"
    "    float lM  = dot(rgbM,  luma);\n"
    "    float lMin = min(lM, min(min(lNW, lNE), min(lSW, lSE)));\n"
    "    float lMax = max(lM, max(max(lNW, lNE), max(lSW, lSE)));\n"
    "\n"
    "    vec2 dir;\n"
    "    dir.x = -((lNW + lNE) - (lSW + lSE));\n"
    "    dir.y =  ((lNW + lSW) - (lNE + lSE));\n"
    "    float dirReduce = max((lNW + lNE + lSW + lSE) * (0.25 * REDUCE_MUL), REDUCE_MIN);\n"
    "    float rcpDirMin = 1.0 / (min(abs(dir.x), abs(dir.y)) + dirReduce);\n"
    "    dir = clamp(dir * rcpDirMin, vec2(-SPAN_MAX), vec2(SPAN_MAX)) * px;\n"
    "\n"
    "    vec3 rgbA = 0.5 * (texture2D(Texture, uv + dir * (1.0/3.0 - 0.5)).rgb\n"
    "                     + texture2D(Texture, uv + dir * (2.0/3.0 - 0.5)).rgb);\n"
    "    vec3 rgbB = rgbA * 0.5 + 0.25 * (texture2D(Texture, uv - dir * 0.5).rgb\n"
    "                                   + texture2D(Texture, uv + dir * 0.5).rgb);\n"
    "    float lB = dot(rgbB, luma);\n"
    "    gl_FragColor = vec4((lB < lMin || lB > lMax) ? rgbA : rgbB, 1.0);\n"
    "}\n"
    "#endif\n"
    "\n";

static const char src_software_look[] =
    "/*\n"
    "    software-look -- snap every pixel to the game's own 256 colour palette,\n"
    "    for Doom Legacy Arcade.  OpenGL's smooth lighting then bands the way the\n"
    "    software renderer's colormaps do.\n"
    "\n"
    "    This program is free software; you can redistribute it and/or modify it\n"
    "    under the terms of the GNU General Public License as published by the Free\n"
    "    Software Foundation; either version 2 of the License, or (at your option)\n"
    "    any later version.\n"
    "\n"
    "    Palette is a 512x512 lookup built by ogl_shader.c from PLAYPAL: 64 levels\n"
    "    per channel, laid out as an 8x8 grid of 64x64 red/green tiles, one tile\n"
    "    per blue level, each texel holding the nearest palette colour.\n"
    "*/\n"
    "\n"
    "#if defined(VERTEX)\n"
    "attribute vec4 VertexCoord;\n"
    "attribute vec4 TexCoord;\n"
    "varying vec2 uv;\n"
    "uniform mat4 MVPMatrix;\n"
    "void main()\n"
    "{\n"
    "    gl_Position = MVPMatrix * VertexCoord;\n"
    "    uv = TexCoord.xy;\n"
    "}\n"
    "\n"
    "#elif defined(FRAGMENT)\n"
    "uniform sampler2D Texture;\n"
    "uniform sampler2D Palette;\n"
    "varying vec2 uv;\n"
    "\n"
    "void main()\n"
    "{\n"
    "    vec3 q = floor(clamp(texture2D(Texture, uv).rgb, 0.0, 1.0) * 63.0 + 0.5);\n"
    "    vec2 tile = vec2(mod(q.b, 8.0), floor(q.b / 8.0));\n"
    "    vec2 p = (tile * 64.0 + q.rg + 0.5) / 512.0;\n"
    "    gl_FragColor = vec4(texture2D(Palette, p).rgb, 1.0);\n"
    "}\n"
    "#endif\n"
    "\n";

static const char src_vhs[] =
    "/*\n"
    "    vhs -- a worn videotape, for Doom Legacy Arcade.\n"
    "\n"
    "    This program is free software; you can redistribute it and/or modify it\n"
    "    under the terms of the GNU General Public License as published by the Free\n"
    "    Software Foundation; either version 2 of the License, or (at your option)\n"
    "    any later version.\n"
    "\n"
    "    What a VHS picture does, roughly in the order it is done here:\n"
    "    - the lines wobble sideways a little, and a noisy tracking band drifts\n"
    "      up the screen, tearing the lines it crosses;\n"
    "    - the bottom few lines are torn sideways (head switching);\n"
    "    - brightness keeps about 3 MHz of detail, colour far less, and the colour\n"
    "      lands a little to the right of the picture it belongs to;\n"
    "    - colour is washed out, blacks are lifted, and there is snow.\n"
    "\n"
    "    Runs on the full-size frame and measures everything as a fraction of the\n"
    "    screen, so it looks the same at any resolution.  Needs linear sampling.\n"
    "    Time is in seconds, from ogl_shader.c.\n"
    "*/\n"
    "\n"
    "#pragma parameter chromaSmear  \"Colour smear\"          1.0  0.0 3.0 0.1\n"
    "#pragma parameter wobble       \"Line wobble\"           1.0  0.0 3.0 0.1\n"
    "#pragma parameter tracking     \"Tracking band\"         1.0  0.0 1.0 1.0\n"
    "#pragma parameter snow         \"Snow\"                  0.05 0.0 0.3 0.01\n"
    "#pragma parameter saturation   \"Saturation\"            0.8  0.0 1.5 0.05\n"
    "\n"
    "#if defined(VERTEX)\n"
    "attribute vec4 VertexCoord;\n"
    "attribute vec4 TexCoord;\n"
    "varying vec2 uv;\n"
    "uniform mat4 MVPMatrix;\n"
    "void main()\n"
    "{\n"
    "    gl_Position = MVPMatrix * VertexCoord;\n"
    "    uv = TexCoord.xy;\n"
    "}\n"
    "\n"
    "#elif defined(FRAGMENT)\n"
    "uniform sampler2D Texture;\n"
    "uniform float Time;\n"
    "uniform float chromaSmear;\n"
    "uniform float wobble;\n"
    "uniform float tracking;\n"
    "uniform float snow;\n"
    "uniform float saturation;\n"
    "varying vec2 uv;\n"
    "\n"
    "float hash(vec2 p)\n"
    "{\n"
    "    return fract(sin(dot(p, vec2(12.9898, 78.233))) * 43758.5453);\n"
    "}\n"
    "\n"
    "vec3 rgb2yiq(vec3 c)\n"
    "{\n"
    "    return vec3(dot(c, vec3(0.299,  0.587,  0.114)),\n"
    "                dot(c, vec3(0.596, -0.274, -0.322)),\n"
    "                dot(c, vec3(0.211, -0.523,  0.312)));\n"
    "}\n"
    "\n"
    "vec3 yiq2rgb(vec3 y)\n"
    "{\n"
    "    return vec3(y.x + 0.956 * y.y + 0.621 * y.z,\n"
    "                y.x - 0.272 * y.y - 0.647 * y.z,\n"
    "                y.x - 1.106 * y.y + 1.703 * y.z);\n"
    "}\n"
    "\n"
    "void main()\n"
    "{\n"
    "    // uv.y is 0 at the bottom of the screen.\n"
    "    float line = floor(uv.y * 240.0);\n"
    "    float tic = floor(Time * 30.0);\n"
    "    vec2 st = uv;\n"
    "\n"
    "    // Wobble: a slow wave down the screen, plus a little per-line jitter.\n"
    "    float shift = sin(uv.y * 25.0 + Time * 1.7) * 0.0007\n"
    "                + (hash(vec2(line, tic)) - 0.5) * 0.0010;\n"
    "    shift *= wobble;\n"
    "\n"
    "    // Tracking band.  Every 20 seconds it drifts up the screen once, taking\n"
    "    // about 6, and is gone the rest of the time.  Toned down after the first\n"
    "    // version (on screen most of the time, twice as tall, three times the\n"
    "    // tear) proved too much on the cabinet.\n"
    "    float band = 0.0;\n"
    "    if( tracking > 0.5 )\n"
    "    {\n"
    "        float d = uv.y - fract(Time / 20.0) * 4.0 + 0.1;\n"
    "        band = smoothstep(0.018, 0.0, abs(d));\n"
    "        shift += band * (hash(vec2(line, tic + 7.0)) - 0.5) * 0.01;\n"
    "    }\n"
    "\n"
    "    // Head switching: the bottom lines tear to the right.\n"
    "    float head = smoothstep(0.018, 0.0, uv.y);\n"
    "    shift += head * (0.01 + 0.01 * hash(vec2(line, tic + 3.0)));\n"
    "\n"
    "    st.x += shift;\n"
    "\n"
    "    // Brightness: about 1/300 of the width.  Colour: about 1/60, shifted right.\n"
    "    float lw = 1.0 / 300.0;\n"
    "    float cw = chromaSmear / 60.0;\n"
    "    vec3 c0 = texture2D(Texture, st + vec2(-lw, 0.0)).rgb;\n"
    "    vec3 c1 = texture2D(Texture, st).rgb;\n"
    "    vec3 c2 = texture2D(Texture, st + vec2( lw, 0.0)).rgb;\n"
    "    float y = rgb2yiq(c0 * 0.25 + c1 * 0.5 + c2 * 0.25).x;\n"
    "\n"
    "    vec2 iq = vec2(0.0);\n"
    "    float cs = -0.35 * cw;  // colour trails behind\n"
    "    iq += rgb2yiq(texture2D(Texture, st + vec2(cs - cw,        0.0)).rgb).yz;\n"
    "    iq += rgb2yiq(texture2D(Texture, st + vec2(cs - cw * 0.5,  0.0)).rgb).yz;\n"
    "    iq += rgb2yiq(texture2D(Texture, st + vec2(cs,             0.0)).rgb).yz;\n"
    "    iq += rgb2yiq(texture2D(Texture, st + vec2(cs + cw * 0.5,  0.0)).rgb).yz;\n"
    "    iq += rgb2yiq(texture2D(Texture, st + vec2(cs + cw,        0.0)).rgb).yz;\n"
    "    iq *= 0.2 * saturation;\n"
    "\n"
    "    vec3 rgb = yiq2rgb(vec3(y, iq));\n"
    "\n"
    "    // Snow, heavier in the tracking band and the torn lines.\n"
    "    float n = hash(floor(uv * vec2(640.0, 480.0)) + vec2(tic * 1.3, tic * 0.7)) - 0.5;\n"
    "    rgb += n * (snow + band * 0.2 + head * 0.3);\n"
    "    // A few bright streaks in the band.\n"
    "    rgb += band * step(0.993, hash(vec2(floor(uv.x * 160.0), line + tic))) * 0.3;\n"
    "\n"
    "    // Lifted blacks, softer whites.\n"
    "    rgb = rgb * 0.9 + 0.04;\n"
    "    gl_FragColor = vec4(clamp(rgb, 0.0, 1.0), 1.0);\n"
    "}\n"
    "#endif\n"
    "\n";

static const char src_colour[] =
    "/*\n"
    "    colour -- whole-screen colour looks for Doom Legacy Arcade: greyscale,\n"
    "    sepia and night vision.  One file, compiled once per look with LOOK\n"
    "    defined by ogl_shader.c (1 greyscale, 2 sepia, 3 night vision).\n"
    "\n"
    "    This program is free software; you can redistribute it and/or modify it\n"
    "    under the terms of the GNU General Public License as published by the Free\n"
    "    Software Foundation; either version 2 of the License, or (at your option)\n"
    "    any later version.\n"
    "\n"
    "    Runs on the full-size frame.  Time is in seconds, from ogl_shader.c.\n"
    "*/\n"
    "\n"
    "#if defined(VERTEX)\n"
    "attribute vec4 VertexCoord;\n"
    "attribute vec4 TexCoord;\n"
    "varying vec2 uv;\n"
    "uniform mat4 MVPMatrix;\n"
    "void main()\n"
    "{\n"
    "    gl_Position = MVPMatrix * VertexCoord;\n"
    "    uv = TexCoord.xy;\n"
    "}\n"
    "\n"
    "#elif defined(FRAGMENT)\n"
    "uniform sampler2D Texture;\n"
    "uniform vec2 OutputSize;\n"
    "uniform float Time;\n"
    "varying vec2 uv;\n"
    "\n"
    "float hash(vec2 p)\n"
    "{\n"
    "    return fract(sin(dot(p, vec2(12.9898, 78.233))) * 43758.5453);\n"
    "}\n"
    "\n"
    "void main()\n"
    "{\n"
    "    vec3 c = texture2D(Texture, uv).rgb;\n"
    "    float l = dot(c, vec3(0.299, 0.587, 0.114));\n"
    "\n"
    "#if LOOK == 1\n"
    "    // Greyscale.\n"
    "    c = vec3(l);\n"
    "\n"
    "#elif LOOK == 2\n"
    "    // Sepia: the usual print-toning matrix, eased back a little so dark\n"
    "    // corridors do not turn to mud.\n"
    "    vec3 s = vec3(dot(c, vec3(0.393, 0.769, 0.189)),\n"
    "                  dot(c, vec3(0.349, 0.686, 0.168)),\n"
    "                  dot(c, vec3(0.272, 0.534, 0.131)));\n"
    "    c = mix(vec3(l), s, 0.85);\n"
    "\n"
    "#elif LOOK == 3\n"
    "    // Night vision: amplified brightness in phosphor green, sensor noise,\n"
    "    // a faint line structure and a round eyepiece.\n"
    "    float tic = floor(Time * 30.0);\n"
    "    float amp = pow(l, 0.6) * 1.35;\n"
    "    amp += (hash(floor(uv * OutputSize * 0.5) + vec2(tic, tic * 1.7)) - 0.5) * 0.18;\n"
    "    amp *= 0.9 + 0.1 * sin(uv.y * OutputSize.y * 1.2);\n"
    "    vec2 d = (uv - 0.5) * vec2(OutputSize.x / OutputSize.y, 1.0);\n"
    "    amp *= smoothstep(1.1, 0.7, length(d));  // wide enough to keep the HUD readable\n"
    "    c = clamp(amp, 0.0, 1.2) * vec3(0.35, 1.0, 0.35);\n"
    "#endif\n"
    "\n"
    "    gl_FragColor = vec4(clamp(c, 0.0, 1.0), 1.0);\n"
    "}\n"
    "#endif\n"
    "\n";

static const char src_game_boy[] =
    "/*\n"
    "    game-boy -- the original Game Boy's four shades of green, for Doom Legacy\n"
    "    Arcade, with an ordered dither so gradients survive the four levels.\n"
    "\n"
    "    This program is free software; you can redistribute it and/or modify it\n"
    "    under the terms of the GNU General Public License as published by the Free\n"
    "    Software Foundation; either version 2 of the License, or (at your option)\n"
    "    any later version.\n"
    "\n"
    "    Runs on the downsampled frame (about 200 lines, see ogl_shader.c), drawn\n"
    "    with nearest sampling so each game-sized pixel is a solid block, and the\n"
    "    dither works on those blocks rather than on screen pixels.\n"
    "*/\n"
    "\n"
    "#if defined(VERTEX)\n"
    "attribute vec4 VertexCoord;\n"
    "attribute vec4 TexCoord;\n"
    "varying vec2 uv;\n"
    "uniform mat4 MVPMatrix;\n"
    "void main()\n"
    "{\n"
    "    gl_Position = MVPMatrix * VertexCoord;\n"
    "    uv = TexCoord.xy;\n"
    "}\n"
    "\n"
    "#elif defined(FRAGMENT)\n"
    "uniform sampler2D Texture;\n"
    "uniform vec2 TextureSize;\n"
    "varying vec2 uv;\n"
    "\n"
    "void main()\n"
    "{\n"
    "    vec2 cell = floor(uv * TextureSize);\n"
    "    vec3 c = texture2D(Texture, (cell + 0.5) / TextureSize).rgb;\n"
    "    // Brightened well up: Doom is dark, and the darkest shade is nearly black,\n"
    "    // so without this most of a level lands on it.\n"
    "    float l = clamp(pow(dot(c, vec3(0.299, 0.587, 0.114)), 0.6) * 1.25, 0.0, 1.0);\n"
    "\n"
    "    // 2x2 Bayer threshold, spread over one step of the four levels.\n"
    "    vec2 m = mod(cell, 2.0);\n"
    "    float bayer = (m.x * 2.0 + m.y * 3.0 - 4.0 * m.x * m.y);  // 0 2 3 1\n"
    "    float level = floor(clamp(l * 3.0 + (bayer + 0.5) / 4.0 - 0.5, 0.0, 3.0));\n"
    "\n"
    "    vec3 shade = vec3(0.059, 0.220, 0.059);                      // #0f380f\n"
    "    if( level > 0.5 )  shade = vec3(0.188, 0.384, 0.188);        // #306230\n"
    "    if( level > 1.5 )  shade = vec3(0.545, 0.675, 0.059);        // #8bac0f\n"
    "    if( level > 2.5 )  shade = vec3(0.608, 0.737, 0.059);        // #9bbc0f\n"
    "    gl_FragColor = vec4(shade, 1.0);\n"
    "}\n"
    "#endif\n"
    "\n";

